changeSet.sql:
create or alter procedure GetDynamicAssets @assetTypeId int, @userId int, @filter nvarchar(250), @pageNumber int, @pageSize int, @sortField nvarchar(250), @sortDirection nvarchar(10), @filters [dbo].[AssetFiltersTable] readonly as begin set nocount on;
if @sortField = '' begin set @sortField = null end
if @filter = '' begin set @filter = null end
set @pageNumber = @pageNumber * @pageSize
declare @admin bit select @admin = IsAdministrator from reporting.Global_Resource where ResourceID = @userId
declare @parentIntersectTypeId int = null select @parentIntersectTypeId = I.ID from IntersectType I inner join AssetType O on O.ID = @assetTypeId and O.Object = I.Object and O.ObjectID = I.ObjectID inner join [Predicate] P on P.ID = I.PredicateID and P.[Type] = case when O.Class in (2,6) then 4 else 3 end
drop table if exists #ft;
select * into #ft from FieldType where AssetTypeID = @assetTypeId and [Type] not in ('File', 'Hidden', 'Password', 'FusionLookup', 'Attribute', 'FilteredLookup', 'ComplexRelationLookup', 'DataTableSelect', 'OwnershipLookup', 'RefListRelationship') order by ColumnOrder, [FriendlyName];
alter table #ft add DataType varchar(25) alter table #ft add ColumnName varchar(250) alter table #ft add ColumnStatement varchar(250) alter table #ft add OrderStatement varchar(250) alter table #ft add JoinStatement varchar(2500) alter table #ft add FilterStatement varchar(2500) alter table #ft add TxtId varchar(25)
update #ft set TxtId = cast(ID as nvarchar), DataType = case [Type] when 'Boolean' then 'bit' when 'Decimal' then 'float' when 'DateTime' then 'datetime' when 'Date' then 'date' when 'Number' then 'long' else 'nvarchar' end, ColumnName = 'Field' + cast(ID as nvarchar);--REPLACE(REPLACE(Name, ' ', ''), '''', '');--'F' + cast(ID as nvarchar);
--json field from relationship update T set T.JoinStatement = ' inner join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' inner join FieldType FT'+TxtId+'R on FT'+TxtId+'R.ID = FT'+TxtId+'.LookupObjectFieldTypeID cross apply openjson(FT'+TxtId+'R.Definition) with (FieldTypeID int ''$.FieldTypeID'', DataType varchar(50) ''$.DataType'', [Path] varchar(250) ''$.Path'') FT'+TxtId+'RD left join [Intersect] FT'+TxtId+'_REL with(nolock) on FT'+TxtId+'.LookupObjectType = ''IntersectType'' and FT'+TxtId+'_REL.IntersectTypeID = FT'+TxtId+'.LookupObjectID and ( (FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID) or (FT'+TxtId+'_REL.Object = A.Object and FT'+TxtId+'_REL.ObjectID = A.ObjectID) ) left join Field F'+TxtId+'R with(nolock) on F'+TxtId+'R.ObjectType = case when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.Object else FT'+TxtId+'_REL.Subject end and F'+TxtId+'R.ObjectID = case when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.ObjectID else FT'+TxtId+'_REL.SubjectID end and F'+TxtId+'R.FieldTypeID = FT'+TxtId+'RD.FieldTypeID left join FieldJsonProperty F'+TxtId+'RP with(nolock) on F'+TxtId+'RP.FieldID = F'+TxtId+'R.ID and F'+TxtId+'RP.[Path] = FT'+TxtId+'RD.[Path]', T.ColumnStatement = 'try_cast(F'+TxtId+'RP.Value as '+DataType+')', T.OrderStatement = 'try_cast(F'+TxtId+'RP.Value as '+DataType+')', T.FilterStatement = case when @filter is not null then '(F'+TxtId+'RP.Value like @filter)' when T.ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'RP.Value like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' else '' end from #ft T inner join FieldType S on S.ID = T.LookupObjectFieldTypeID and S.[Type] = 'JsonElement' where T.[Type] = 'FieldFromRelationship';
--non-json field from relationship update T set T.JoinStatement = ' inner join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' left join [Intersect] FT'+TxtId+'_REL with(nolock) on FT'+TxtId+'.LookupObjectType = ''IntersectType'' and FT'+TxtId+'_REL.IntersectTypeID = FT'+TxtId+'.LookupObjectID and ( (FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID) or (FT'+TxtId+'_REL.Object = A.Object and FT'+TxtId+'_REL.ObjectID = A.ObjectID) ) left join Field F'+TxtId+'R with(nolock) on F'+TxtId+'R.ObjectType = case when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.Object else FT'+TxtId+'_REL.Subject end and F'+TxtId+'R.ObjectID = case when FT'+TxtId+'_REL.Subject = A.Object and FT'+TxtId+'_REL.SubjectID = A.ObjectID then FT'+TxtId+'_REL.ObjectID else FT'+TxtId+'_REL.SubjectID end and F'+TxtId+'R.FieldTypeID = FT'+TxtId+'.LookupObjectFieldTypeID', T.ColumnStatement = 'try_cast(F'+TxtId+'R.FormattedValue as '+DataType+')', T.OrderStatement = 'try_cast(F'+TxtId+'R.FormattedValue as '+DataType+')', T.FilterStatement = case when @filter is not null then '(F'+TxtId+'R.FormattedValue like @filter)' when T.ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'R.FormattedValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' else '' end from #ft T inner join FieldType S on S.ID = T.LookupObjectFieldTypeID and S.[Type] <> 'JsonElement' where T.[Type] = 'FieldFromRelationship';
--json element update T set T.JoinStatement = ' inner join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' cross apply openjson(FT'+TxtId+'.Definition) with (FieldTypeID int ''$.FieldTypeID'', DataType varchar(50) ''$.DataType'', [Path] varchar(250) ''$.Path'') FT'+TxtId+'D left join Field F'+TxtId+' with(nolock) on F'+TxtId+'.FieldTypeID = '+cast(D.FieldTypeID as nvarchar)+' and F'+TxtId+'.AssetID = A.ID left join FieldJsonProperty F'+TxtId+'P with(nolock) on F'+TxtId+'P.FieldID = F'+TxtId+'.ID and F'+TxtId+'P.[Path] = FT'+TxtId+'D.[Path]', T.ColumnStatement = 'try_cast(F'+TxtId+'P.Value as '+D.DataType+')', T.OrderStatement = 'try_cast(F'+TxtId+'P.Value as '+D.DataType+')', T.FilterStatement = case when @filter is not null then '(F'+TxtId+'P.Value like @filter)' when T.ID in (select TypeID from @filters where FilterType = 'F') then 'F'+TxtId+'P.Value like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' else '' end from #ft T cross apply openjson(T.[Definition]) with (FieldTypeID int '$.FieldTypeID', DataType varchar(50) '$.DataType', [Path] varchar(250) '$.Path') D where T.[Type] = 'JsonElement';
--relationship update #ft set JoinStatement = ' left join FieldType FT'+TxtId+' with(nolock) on FT'+TxtId+'.ID = '+TxtId+' and FT'+TxtId+'.LookupObjectType = ''IntersectType'' left join [Intersect] F'+TxtId+'R with(nolock) on F'+TxtId+'R.IntersectTypeID = FT'+TxtId+'.LookupObjectID and ( (F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID) or (F'+TxtId+'R.Object = A.Object and F'+TxtId+'R.ObjectID = A.ObjectID) ) outer apply dbo.GetRelationshipDisplayValue( case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.Object else F'+TxtId+'R.Subject end, case when F'+TxtId+'R.Subject = A.Object and F'+TxtId+'R.SubjectID = A.ObjectID then F'+TxtId+'R.ObjectID else F'+TxtId+'R.SubjectID end ) as F'+TxtId, ColumnStatement = 'F'+TxtId+'.DisplayValue', OrderStatement = 'F'+TxtId+'.DisplayValue', FilterStatement = case when @filter is not null then '(F'+TxtId+'.DisplayValue like @filter)' when ID in (select TypeID from @filters where FilterType = 'R') then 'F'+TxtId+'.DisplayValue like (select top 1 FilterValues from @filters where TypeID = FT'+TxtId+'.ID)' else '' end where [Type] = 'Relationship';
--simple field update #ft set JoinStatement = 'left join FieldDetail F'+TxtId+' on F'+TxtId+'.FieldTypeID = '+TxtId+' and F'+TxtId+'.AssetID = A.ID', ColumnStatement = 'F'+TxtId+'.FormattedValue', OrderStatement = 'F'+TxtId+'.FormattedValue', FilterStatement = case when @filter is not null then '(F'+TxtId+'.FormattedValue like @filter)' when ID in (select TypeID from @filters where FilterType = 'F') then 'exists(select 1 from @filters where TypeID = F'+TxtId+'.FieldTypeID and F'+TxtId+'.FormattedValue like FilterValues)' else '' end where JoinStatement is null;
declare @countSql nvarchar(max), @sql nvarchar(max), @orderSql nvarchar(500), @filterSql nvarchar(500) = '', @parentColumns nvarchar(500) = '', @parentJoin nvarchar(500) = '', @editRightsColumns nvarchar(2500) = '', @hasFilters bit = 0
if @admin = 1 begin set @editRightsColumns = '1 as P_CanEdit, 1 as P_CanDelete, ' end else begin set @editRightsColumns = ' case when exists (select 1 from UserAssetPermissions(@userId,A.AssetTypeID) u where u.PermissionsBitMask & 2 = 2 and (u.AssetID = A.ID or (u.AssetID = 0 and u.AssetTypeID = A.AssetTypeID)) ) then 1 else 0 end as P_CanEdit, case when exists (select 1 from UserAssetPermissions(@userId,A.AssetTypeID) u where u.PermissionsBitMask & 4 = 4 and (u.AssetID = A.ID or (u.AssetID = 0 and u.AssetTypeID = A.AssetTypeID)) ) then 1 else 0 end as P_CanDelete, ' end;
-- Handle custom-provided sort if @sortField is not null begin select @sortField = ColumnStatement from #ft where ColumnName = @sortField if @sortField = '' begin set @sortField = 'A.ID' end if @sortDirection = 'desc' begin set @sortDirection = 'desc' end else begin set @sortDirection = 'asc' end
set @orderSql = REPLACE(@sortField, '''', '''''') + ' ' + @sortDirection end else begin select @orderSql = string_agg(OrderStatement, ', ') from (select top 100 percent OrderStatement from #ft where SortOrder not in (0,99) and (IsListable = 1 or coalesce(FilterStatement,'')<>'') order by SortOrder) O if @orderSql = '' or @orderSql is null begin set @orderSql = 'A.ID asc' end end
-- Handle parent SQL if @parentIntersectTypeId is not null begin set @parentColumns = 'arp.ParentArtifactID as ParentID, parp.DisplayValue as Parent, '''' as ParentUrl, ' set @parentJoin = ' inner join [utility].[ArtifactAssetParent] arp on A.ID = arp.AssetID inner join AssetDisplayValue parp on parp.AssetID = arp.ParentAssetID' end
set @countSql = 'select count(1)' set @countSql = @countSql + ' from Asset A ' select @countSql = @countSql + string_agg(JoinStatement, ' ') from #ft where (coalesce(JoinStatement,'') <> '') and (IsListable = 1 OR coalesce(FilterStatement,'') <> '') set @countSql = @countSql + @parentJoin set @countSql = @countSql + ' where A.AssetTypeID = '+cast(@assetTypeId as nvarchar)+' and A.State = 1'
-- Handle base filters if exists(select 1 from #ft where coalesce(FilterStatement,'') <> '') begin select @filterSql = string_agg(FilterStatement, ' or ') from #ft where coalesce(FilterStatement,'') <> '' set @filterSql = 'and (' + @filterSql + ')' set @hasFilters = 1 end;
-- Handle attribute filters. if exists(select 1 from @filters where FilterType = 'A') begin set @hasFilters = 1 set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and A.ObjectID in (select ObjectID from AttributeDetail A inner join @filters F on F.FilterType = ''A'' and F.TypeID = A.AttributeTypeID and A.FormattedValue like F.FilterValues)' end
--Handle parent filters if exists(select 1 from @filters where FilterType = 'P') begin set @hasFilters = 1 set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and parp.DisplayValue like (select top 1 FilterValues from @filters where FilterType = ''P'')' end
-- Handle ownership filters. if exists(select 1 from @filters where FilterType = 'O') begin set @hasFilters = 1 set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and A.ID in (select AssetID from ResponsibilityDetail RD inner join @filters F on F.FilterType = ''O'' cross apply openjson(F.FilterValues) with (SecurityAsset varchar(1) ''$.SecurityAsset'', SecurityAssetID int ''$.SecurityAssetID'', ResponsibilityTypeID int ''$.ResponsibilityTypeID'') O where RD.SecurityAsset = O.SecurityAsset and RD.SecurityAssetID = O.SecurityAssetID and RD.ResponsibilityTypeID = O.ResponsibilityTypeID )' end
-- Handle relationship filters. if exists(select 1 from @filters where FilterType = 'R') begin set @hasFilters = 1 declare @relationFilters table (RowId int identity, [Operator] varchar(25) NULL, [TypeID] [int] NOT NULL, [OptionalIdentifier] varchar(50) NULL, [FilterValues] [nvarchar](max) NOT NULL) insert into @relationFilters select [Operator], [TypeID], [OptionalIdentifier], [FilterValues] from @filters where FilterType = 'R' declare @current int = 1, @max int, @operator varchar(25), @typeID nvarchar(30), @optionalIdentifier varchar(50), @filterValues nvarchar(max) select @max = max(RowId) from @relationFilters while @current <= @max begin select @operator = [Operator], @typeID = cast(TypeID as nvarchar), @optionalIdentifier = OptionalIdentifier, @filterValues = FilterValues from @relationFilters where RowId = @current
if @operator = 'OR' begin set @filterSql = iif(@filterSql is not null, @filterSql, '') + ' and A.ObjectID in ( select ObjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Subject = ''' + @optionalIdentifier + ''' and SubjectID in (' + @filterValues + ') union select SubjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Object = ''' + @optionalIdentifier + ''' and ObjectID in (' + @filterValues + ') )' end else begin declare @filterAndRelations table (FindID int, SqlStatement nvarchar(500)) insert into @filterAndRelations select value, 'and A.ObjectID in ( select ObjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Subject = ''' + @optionalIdentifier + ''' and SubjectID = '+cast(value as nvarchar)+' union select SubjectID from [Intersect] with(nolock) where IntersectTypeID = '+@typeID+' and Object = ''' + @optionalIdentifier + ''' and ObjectID = '+cast(value as nvarchar)+' )' from string_split(@filterValues, ',') select @filterSql = iif(@filterSql is not null, @filterSql, '') + string_agg(SqlStatement, ' ') from @filterAndRelations end
set @current = @current + 1 end end
if @hasFilters = 1 begin set @countSql = @countSql + @filterSql end set @countSql = @countSql + ' and not exists (select 1 from AssetTypesUserCantRead(@userId) u where u.AssetTypeID = @assetTypeId) and not exists (select 1 from AssetsByTypeUserCantRead(@userId,@assetTypeId) u where u.AssetID = A.ID)'
set @sql = 'select A.AssetTypeID, A.ID, A.ObjectID, A.Uid, ' + @parentColumns + @editRightsColumns select @sql = @sql + string_agg(ColumnStatement + ' as ' + ColumnName, ', ') from #ft where coalesce(ColumnStatement,'') <> '' and IsListable = 1 set @sql = @sql + ' from Asset A ' select @sql = @sql + string_agg(JoinStatement, ' ') from #ft where (coalesce(JoinStatement,'') <> '') and (IsListable = 1 OR coalesce(FilterStatement,'') <>'') set @sql = @sql + @parentJoin set @sql = @sql + ' where A.AssetTypeID = '+cast(@assetTypeId as nvarchar)+' and A.State = 1'
if @hasFilters = 1 begin set @sql = @sql + @filterSql end
set @sql = @sql + ' and not exists (select 1 from AssetTypesUserCantRead(@userId) u where u.AssetTypeID = @assetTypeId) and not exists (select 1 from AssetsByTypeUserCantRead(@userId,@assetTypeId) u where u.AssetID = A.ID)' set @sql = @sql + ' order by '+@orderSql+' OFFSET(@pageNumber) ROWS FETCH NEXT (@pageSize) ROWS ONLY'
declare @parameters nvarchar(max) set @parameters = '@assetTypeId int, @filter nvarchar(250), @userId int, @pageNumber int, @pageSize int, @filters [dbo].[AssetFiltersTable] readonly' --select @sql --select @filterSql exec sp_executesql @countSql, @parameters, @assetTypeId = @assetTypeId, @filter = @filter, @userId = @userId, @pageNumber = @pageNumber, @pageSize = @pageSize, @filters = @filters exec sp_executesql @sql, @parameters, @assetTypeId = @assetTypeId, @filter = @filter, @userId = @userId, @pageNumber = @pageNumber, @pageSize = @pageSize, @filters = @filters end
